using namespace std;

class Solution {
public:
    int minDeletionCost(string s, vector<int>& cost) {
        unordered_map<char, int> char_costs;
        int total = 0;
        int max_retained = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            char_costs[s[i]] += cost[i];
            total += cost[i];
            max_retained = max(max_retained, char_costs[s[i]]);
        }
        return total - max_retained;
    }
};

import java.util.*;

class Solution {
    public int minDeletionCost(String s, int[] cost) {
        Map<Character, Integer> charCosts = new HashMap<>();
        int total = 0;
        int maxRetained = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int newCost = charCosts.getOrDefault(ch, 0) + cost[i];
            charCosts.put(ch, newCost);
            total += cost[i];
            maxRetained = Math.max(maxRetained, newCost);
        }
        return total - maxRetained;
    }
}

var minDeletionCost = function(s, cost) {
    const charCosts = new Map();
    let total = 0;
    let maxRetained = 0;
    for (let i = 0; i < s.length; i++) {
        const c = cost[i];
        total += c;
        const cur = (charCosts.get(s[i]) || 0) + c;
        charCosts.set(s[i], cur);
        maxRetained = Math.max(maxRetained, cur);
    }
    return total - maxRetained;
};
